import sys

def solve():
    raw = sys.stdin.read().split()
    if not raw:
        return
    N = int(raw[0])
    idx = 1
    grid = []
    for i in range(N):
        row = []
        for j in range(N):
            row.append(int(raw[idx]))
            idx += 1
        grid.append(row)

    if N == 1:
        if grid[0][0] == 1:
            print("")
        else:
            print("-1")
        return

    if grid[0][0] == 0 or grid[N-1][N-1] == 0:
        print("-1")
        return

    paths = []
    visited = [[False]*N for _ in range(N)]

    # Directions in lexicographical order: 'D', 'L', 'R', 'U'
    dirs = [('D', 1, 0), ('L', 0, -1), ('R', 0, 1), ('U', -1, 0)]

    def dfs(r, c, current_path):
        if r == N - 1 and c == N - 1:
            paths.append(''.join(current_path))
            return

        visited[r][c] = True
        for move_char, dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N and not visited[nr][nc] and grid[nr][nc] == 1:
                current_path.append(move_char)
                dfs(nr, nc, current_path)
                current_path.pop()
        visited[r][c] = False

    dfs(0, 0, [])
    if paths:
        print(*(paths))
    else:
        print("-1")

if __name__ == '__main__':
    solve()

