import java.util.*;
import java.io.*;

public class Main {
    static int N;
    static int[][] grid;
    static boolean[][] visited;
    static List<String> paths = new ArrayList<>();
    static char[] dirChars = {'D', 'L', 'R', 'U'};
    static int[] dr = {1, 0, 0, -1};
    static int[] dc = {0, -1, 1, 0};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) line = br.readLine();
        if (line == null) return;
        N = Integer.parseInt(line.trim());
        grid = new int[N][N];
        visited = new boolean[N][N];

        StringTokenizer st = null;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                while (st == null || !st.hasMoreTokens()) {
                    line = br.readLine();
                    if (line == null) break;
                    st = new StringTokenizer(line);
                }
                grid[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        if (N == 1) {
            if (grid[0][0] == 1) System.out.println("");
            else System.out.println("-1");
            return;
        }
        if (grid[0][0] == 0 || grid[N-1][N-1] == 0) {
            System.out.println("-1");
            return;
        }

        StringBuilder sb = new StringBuilder();
        dfs(0, 0, sb);

        if (paths.isEmpty()) {
            System.out.println("-1");
        } else {
            StringBuilder out = new StringBuilder();
            for (int i = 0; i < paths.size(); i++) {
                if (i > 0) out.append(" ");
                out.append(paths.get(i));
            }
            System.out.println(out.toString());
        }
    }

    static void dfs(int r, int c, StringBuilder currentPath) {
        if (r == N - 1 && c == N - 1) {
            paths.add(currentPath.toString());
            return;
        }
        visited[r][c] = true;
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr >= 0 && nr < N && nc >= 0 && nc < N && !visited[nr][nc] && grid[nr][nc] == 1) {
                currentPath.append(dirChars[i]);
                dfs(nr, nc, currentPath);
                currentPath.deleteCharAt(currentPath.length() - 1);
            }
        }
        visited[r][c] = false;
    }
}

