        paths.push_back(path);
        return;
    }
    visited[r][c] = true;
    for (int i = 0; i < 4; i++) {
        int nr = r + dr[i];
        int nc = c + dc[i];
        if (nr >= 0 && nr < N && nc >= 0 && nc < N && !visited[nr][nc] && grid[nr][nc] == 1) {
            path.push_back(dirChars[i]);
            dfs(nr, nc, path);
            path.pop_back();
        }
