    static int[] current;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        N = sc.nextInt();

        cols = new boolean[N + 1];
        diag1 = new boolean[2 * N + 2];
        diag2 = new boolean[2 * N + 2];
        current = new int[N];

        backtrack(1);

        if (results.isEmpty()) {
            System.out.println("-1");
        } else {
            StringBuilder sb = new StringBuilder();
            for (int[] sol : results) {
                sb.append("[");
                for (int i = 0; i < N; i++) {
                    if (i > 0) sb.append(" ");
                    sb.append(sol[i]);
                }
                sb.append("]\n");
            }
            System.out.print(sb.toString());
        }
    }

    static void backtrack(int r) {
        if (r > N) {
            results.add(current.clone());
            return;
        }
        for (int c = 1; c <= N; c++) {
            if (!cols[c] && !diag1[r - c + N] && !diag2[r + c]) {
                cols[c] = true;
                diag1[r - c + N] = true;
                diag2[r + c] = true;
                current[r - 1] = c;

                backtrack(r + 1);

                cols[c] = false;
                diag1[r - c + N] = false;
                diag2[r + c] = false;
            }
        }
    }
}

