import sys

def solve():
    raw = sys.stdin.read().split()
    if not raw:
        return
    K = int(raw[0])
    dict_words = set(raw[1:K+1])
    S = raw[K+1]

    N = len(S)
    results = []

    # Memoized check whether suffix S[i:] can be partitioned
    can_break = [None] * (N + 1)
    can_break[N] = True

    for i in range(N - 1, -1, -1):
        can_break[i] = False
        for j in range(i + 1, N + 1):
            if S[i:j] in dict_words and can_break[j]:
                can_break[i] = True
                break

    if not can_break[0]:
        print("-1")
        return

    def backtrack(start, current_words):
        if start == N:
            results.append("(" + " ".join(current_words) + ")")
            return

        for end in range(start + 1, N + 1):
            word = S[start:end]
            if word in dict_words and can_break[end]:
                current_words.append(word)
                backtrack(end, current_words)
                current_words.pop()

    backtrack(0, [])
    results.sort()
    for res in results:
        print(res)

if __name__ == '__main__':
    solve()

