import java.util.*;
import java.io.*;

public class Main {
    static Set<String> dict = new HashSet<>();
    static String S;
    static int N;
    static boolean[] canBreak;
    static List<String> results = new ArrayList<>();

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) line = br.readLine();
        if (line == null) return;
        int K = Integer.parseInt(line.trim());

        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < K; i++) {
            dict.add(st.nextToken());
        }
        S = br.readLine().trim();
        N = S.length();

        canBreak = new boolean[N + 1];
        canBreak[N] = true;
        for (int i = N - 1; i >= 0; i--) {
            for (int j = i + 1; j <= N; j++) {
                if (dict.contains(S.substring(i, j)) && canBreak[j]) {
                    canBreak[i] = true;
                    break;
                }
            }
        }

        if (!canBreak[0]) {
            System.out.println("-1");
            return;
        }

        List<String> words = new ArrayList<>();
        backtrack(0, words);
        Collections.sort(results);
        for (String r : results) {
            System.out.println(r);
        }
    }

    static void backtrack(int start, List<String> words) {
        if (start == N) {
            StringBuilder sb = new StringBuilder("(");
            for (int i = 0; i < words.size(); i++) {
                if (i > 0) sb.append(" ");
                sb.append(words.get(i));
            }
            sb.append(")");
            results.add(sb.toString());
            return;
        }
        for (int end = start + 1; end <= N; end++) {
            String word = S.substring(start, end);
            if (dict.contains(word) && canBreak[end]) {
                words.add(word);
                backtrack(end, words);
                words.remove(words.size() - 1);
            }
        }
    }
}

