import sys
from collections import deque

def is_valid(s):
    count = 0
    for ch in s:
        if ch == '(':
            count += 1
        elif ch == ')':
            count -= 1
            if count < 0:
                return False
    return count == 0

def solve():
    raw = sys.stdin.read().split()
    if not raw:
        return
    S = raw[0]

    # BFS ensures minimum removals
    queue = deque([S])
    visited = {S}
    found = False
    results = []

    while queue:
        level_size = len(queue)
        for _ in range(level_size):
            curr = queue.popleft()
            if is_valid(curr):
                results.append(curr)
                found = True
            if not found:
                for i in range(len(curr)):
                    if curr[i] not in '()':
                        continue
                    nxt = curr[:i] + curr[i+1:]
                    if nxt not in visited:
                        visited.add(nxt)
                        queue.append(nxt)
        if found:
            break

    results.sort()
    for res in results:
        print(res)

if __name__ == '__main__':
    solve()

