#include <vector>
#include <queue>
#include <unordered_set>
#include <algorithm>

using namespace std;

bool is_valid(const string &s) {
    int count = 0;
    for (char c : s) {
        if (c == '(') count++;
        else if (c == ')') {
            count--;
            if (count < 0) return false;
        }
    }
    return count == 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string S;
    if (!(cin >> S)) return 0;

    queue<string> q;
    unordered_set<string> visited;
    vector<string> results;
    bool found = false;

    q.push(S);
    visited.insert(S);

    while (!q.empty()) {
        int size = q.size();
        for (int k = 0; k < size; k++) {
            string curr = q.front();
            q.pop();
            if (is_valid(curr)) {
                results.push_back(curr);
                found = true;
            }
            if (!found) {
                for (size_t i = 0; i < curr.length(); i++) {
                    if (curr[i] != '(' && curr[i] != ')') continue;
                    string nxt = curr.substr(0, i) + curr.substr(i + 1);
                    if (!visited.count(nxt)) {
                        visited.insert(nxt);
                        q.push(nxt);
                    }
                }
            }
        }
        if (found) break;
    }

    sort(results.begin(), results.end());
    for (const auto &r : results) {
        cout << r << "\n";
    }
    return 0;
}

