import sys

def solve():
    raw = sys.stdin.read().split()
    if not raw:
        return
    V = int(raw[0])
    M = int(raw[1])
    E = int(raw[2])

    adj = [[] for _ in range(V)]
    idx = 3
    for _ in range(E):
        u = int(raw[idx])
        v = int(raw[idx+1])
        adj[u].append(v)
        adj[v].append(u)
        idx += 2

    color = [0] * V

    def is_safe(node, c):
        for neighbor in adj[node]:
            if color[neighbor] == c:
                return False
        return True

    def backtrack(node):
        if node == V:
            return True

        for c in range(1, M + 1):
            if is_safe(node, c):
                color[node] = c
                if backtrack(node + 1):
                    return True
                color[node] = 0
        return False

    print(1 if backtrack(0) else 0)

if __name__ == '__main__':
    solve()

