        if (N <= 4) {
            System.out.println("-1");
            return;
        }

        board = new int[N][N];
        for (int i = 0; i < N; i++) Arrays.fill(board[i], -1);
        board[0][0] = 0;

        if (backtrack(0, 0, 1)) {
            for (int i = 0; i < N; i++) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < N; j++) {
                    if (j > 0) sb.append(" ");
                    sb.append(board[i][j]);
                }
                System.out.println(sb.toString());
            }
