        int cnt = 0;
        for (int[] m : moves) {
            int nr = r + m[0], nc = c + m[1];
            if (nr >= 0 && nr < N && nc >= 0 && nc < N && board[nr][nc] == -1) cnt++;
        }
        return cnt;
    }

    static boolean backtrack(int r, int c, int step) {
        if (step == N * N) return true;
        List<Candidate> cands = new ArrayList<>();
        for (int[] m : moves) {
            int nr = r + m[0], nc = c + m[1];
            if (nr >= 0 && nr < N && nc >= 0 && nc < N && board[nr][nc] == -1) {
                cands.add(new Candidate(countDegree(nr, nc), nr, nc));
            }
        }
        Collections.sort(cands);
        for (Candidate cand : cands) {
            board[cand.r][cand.c] = step;
            if (backtrack(cand.r, cand.c, step + 1)) return true;
            board[cand.r][cand.c] = -1;
        }
        return false;
    }
