    static void backtrack(int idx, int count, long currSum) {
        if (count == targetCount) {
            long otherSum = totalSum - currSum;
            long diff = Math.abs(currSum - otherSum);
            if (diff < minDiff) minDiff = diff;
            return;
        }
        if (idx + (targetCount - count) > N) return;

        backtrack(idx + 1, count + 1, currSum + arr[idx]);
        backtrack(idx + 1, count, currSum);
    }
}

