    if not raw:
        return
    S = list(raw[0])
    K = int(raw[1])
    N = len(S)

    max_num = [''.join(S)]

    def backtrack(idx, rem_k):
        curr_str = ''.join(S)
        if curr_str > max_num[0]:
            max_num[0] = curr_str

        if rem_k == 0 or idx >= N:
            return

        # Find maximum character in S[idx:]
        max_char = max(S[idx:])

        # If current char is already max, move to next position without consuming swap
        if max_char != S[idx]:
            rem_k -= 1

        for j in range(N - 1, idx - 1, -1):
            if S[j] == max_char:
                S[idx], S[j] = S[j], S[idx]
                backtrack(idx + 1, rem_k)
                S[idx], S[j] = S[j], S[idx]

    backtrack(0, K)
    print(max_num[0])

