public class Main {
    static char[] S;
    static int N;
    static String maxNum;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNext()) return;
        String str = sc.next();
        int K = sc.nextInt();

        S = str.toCharArray();
        N = S.length;
        maxNum = str;

        backtrack(0, K);
        System.out.println(maxNum);
    }

    static void backtrack(int idx, int remK) {
        String curr = new String(S);
        if (curr.compareTo(maxNum) > 0) {
            maxNum = curr;
        }
        if (remK == 0 || idx >= N) return;

        char maxChar = S[idx];
        for (int i = idx + 1; i < N; i++) {
            if (S[i] > maxChar) maxChar = S[i];
        }

        int nextK = remK;
        if (maxChar != S[idx]) nextK--;

        for (int j = N - 1; j >= idx; j--) {
            if (S[j] == maxChar) {
                char temp = S[idx];
                S[idx] = S[j];
                S[j] = temp;

                backtrack(idx + 1, nextK);

                temp = S[idx];
                S[idx] = S[j];
                S[j] = temp;
            }
        }
    }
}

