    int fact = 1;
    for (int i = 1; i <= N; i++) {
        numbers.push_back(i);
        fact *= i;
    }

    K--; // 0-based
    string res = "";
    for (int i = N; i >= 1; i--) {
        fact /= i;
        int idx = K / fact;
        res += to_string(numbers[idx]);
        numbers.erase(numbers.begin() + idx);
        K %= fact;
    }
    cout << res << "\n";
    return 0;
}
